structs.Value:
typedef struct Value
{
    DataType dt;
    union v {
        int intV;
        char *stringV;
        float floatV;
        bool boolV;
    } v;
} Value;

structs.RID:
typedef struct RID
{
    int page;
    int slot;
} RID;

structs.Record:
typedef struct Record
{
    RID id;
    char *data;
} Record;

structs.Schema:
typedef struct Schema
{
    int numAttr;
    char **attrNames;
    DataType *dataTypes;
    int *typeLength;
    int *keyAttrs;
    int keySize;
} Schema;

structs.RM_TableData:
typedef struct RM_TableData
{
    char *name;
    Schema *schema;
    void *mgmtData;
} RM_TableData;

structs.Expr:
typedef struct Expr
{
    ExprType type;
    union expr {
        Value *cons;
        int attrRef;
        struct Operator *op;
    } expr;
} Expr;

structs.Operator:
typedef struct Operator
{
    OpType type;
    Expr **args;
} Operator;

