functions.serializeTableInfo:
char *serializeTableInfo(RM_TableData *rel)
{
    VarString *result;
    do
    {
        result = (VarString *)malloc(sizeof(VarString));
        result->size = 0;
        result->bufsize = 100;
        result->buf = calloc(100, 1);
    } while (0);
    do
    {
        char *tmp = malloc(10000);
        sprintf(tmp, "TABLE <%s> with <%i> tuples:\n", rel->name, getNumTuples(rel));
        do
        {
            do
            {
                if (result->bufsize < result->size + strlen(tmp))
                {
                    int newbufsize = result->bufsize;
                    while ((newbufsize *= 2) < result->size + strlen(tmp))
                        ;
                    result->buf = realloc(result->buf, newbufsize);
                }
            } while (0);
            memcpy(result->buf + result->size, tmp, strlen(tmp));
            result->size += strlen(tmp);
        } while (0);
        free(tmp);
    } while (0);
    do
    {
        do
        {
            if (result->bufsize < result->size + strlen(serializeSchema(rel->schema)))
            {
                int newbufsize = result->bufsize;
                while ((newbufsize *= 2) < result->size + strlen(serializeSchema(rel->schema)))
                    ;
                result->buf = realloc(result->buf, newbufsize);
            }
        } while (0);
        memcpy(result->buf + result->size, serializeSchema(rel->schema), strlen(serializeSchema(rel->schema)));
        result->size += strlen(serializeSchema(rel->schema));
    } while (0);
    do
    {
        char *resultStr;
        do
        {
            resultStr = malloc((result->size) + 1);
            memcpy(resultStr, result->buf, result->size);
            resultStr[result->size] = '\0';
        } while (0);
        do
        {
            free(result->buf);
            free(result);
        } while (0);
        return resultStr;
    } while (0);
}

functions.serializeTableContent:
char *serializeTableContent(RM_TableData *rel)
{
    int i;
    VarString *result;
    RM_ScanHandle *sc = (RM_ScanHandle *)malloc(sizeof(RM_ScanHandle));
    Record *r = (Record *)malloc(sizeof(Record));
    do
    {
        result = (VarString *)malloc(sizeof(VarString));
        result->size = 0;
        result->bufsize = 100;
        result->buf = calloc(100, 1);
    } while (0);
    for (i = 0; i < rel->schema->numAttr; i++)
        do
        {
            char *tmp = malloc(10000);
            sprintf(tmp, "%s%s", (i != 0) ? ", " : "", rel->schema->attrNames[i]);
            do
            {
                do
                {
                    if (result->bufsize < result->size + strlen(tmp))
                    {
                        int newbufsize = result->bufsize;
                        while ((newbufsize *= 2) < result->size + strlen(tmp))
                            ;
                        result->buf = realloc(result->buf, newbufsize);
                    }
                } while (0);
                memcpy(result->buf + result->size, tmp, strlen(tmp));
                result->size += strlen(tmp);
            } while (0);
            free(tmp);
        } while (0);
    startScan(rel, sc, ((void *)0));
    while (next(sc, r) != 203)
    {
        do
        {
            do
            {
                if (result->bufsize < result->size + strlen(serializeRecord(r, rel->schema)))
                {
                    int newbufsize = result->bufsize;
                    while ((newbufsize *= 2) < result->size + strlen(serializeRecord(r, rel->schema)))
                        ;
                    result->buf = realloc(result->buf, newbufsize);
                }
            } while (0);
            memcpy(result->buf + result->size, serializeRecord(r, rel->schema),
                   strlen(serializeRecord(r, rel->schema)));
            result->size += strlen(serializeRecord(r, rel->schema));
        } while (0);
        do
        {
            do
            {
                if (result->bufsize < result->size + strlen("\n"))
                {
                    int newbufsize = result->bufsize;
                    while ((newbufsize *= 2) < result->size + strlen("\n"))
                        ;
                    result->buf = realloc(result->buf, newbufsize);
                }
            } while (0);
            memcpy(result->buf + result->size, "\n", strlen("\n"));
            result->size += strlen("\n");
        } while (0);
    }
    closeScan(sc);
    do
    {
        char *resultStr;
        do
        {
            resultStr = malloc((result->size) + 1);
            memcpy(resultStr, result->buf, result->size);
            resultStr[result->size] = '\0';
        } while (0);
        do
        {
            free(result->buf);
            free(result);
        } while (0);
        return resultStr;
    } while (0);
}

