functions.serializeAttr:
char *serializeAttr(Record *record, Schema *schema, int attrNum)
{
    int offset;
    char *attrData;
    VarString *result;
    do
    {
        result = (VarString *)malloc(sizeof(VarString));
        result->size = 0;
        result->bufsize = 100;
        result->buf = calloc(100, 1);
    } while (0);
    attrOffset(schema, attrNum, &offset);
    attrData = record->data + offset;
    switch (schema->dataTypes[attrNum])
    {
    case DT_INT: {
        int val = 0;
        memcpy(&val, attrData, sizeof(int));
        do
        {
            char *tmp = malloc(10000);
            sprintf(tmp, "%s:%i", schema->attrNames[attrNum], val);
            do
            {
                do
                {
                    if (result->bufsize < result->size + strlen(tmp))
                    {
                        int newbufsize = result->bufsize;
                        while ((newbufsize *= 2) < result->size + strlen(tmp))
                            ;
                        result->buf = realloc(result->buf, newbufsize);
                    }
                } while (0);
                memcpy(result->buf + result->size, tmp, strlen(tmp));
                result->size += strlen(tmp);
            } while (0);
            free(tmp);
        } while (0);
    }
    break;
    case DT_STRING: {
        char *buf;
        int len = schema->typeLength[attrNum];
        buf = (char *)malloc(len + 1);
        strncpy(buf, attrData, len);
        buf[len] = '\0';
        do
        {
            char *tmp = malloc(10000);
            sprintf(tmp, "%s:%s", schema->attrNames[attrNum], buf);
            do
            {
                do
                {
                    if (result->bufsize < result->size + strlen(tmp))
                    {
                        int newbufsize = result->bufsize;
                        while ((newbufsize *= 2) < result->size + strlen(tmp))
                            ;
                        result->buf = realloc(result->buf, newbufsize);
                    }
                } while (0);
                memcpy(result->buf + result->size, tmp, strlen(tmp));
                result->size += strlen(tmp);
            } while (0);
            free(tmp);
        } while (0);
        free(buf);
    }
    break;
    case DT_FLOAT: {
        float val;
        memcpy(&val, attrData, sizeof(float));
        do
        {
            char *tmp = malloc(10000);
            sprintf(tmp, "%s:%f", schema->attrNames[attrNum], val);
            do
            {
                do
                {
                    if (result->bufsize < result->size + strlen(tmp))
                    {
                        int newbufsize = result->bufsize;
                        while ((newbufsize *= 2) < result->size + strlen(tmp))
                            ;
                        result->buf = realloc(result->buf, newbufsize);
                    }
                } while (0);
                memcpy(result->buf + result->size, tmp, strlen(tmp));
                result->size += strlen(tmp);
            } while (0);
            free(tmp);
        } while (0);
    }
    break;
    case DT_BOOL: {
        bool val;
        memcpy(&val, attrData, sizeof(bool));
        do
        {
            char *tmp = malloc(10000);
            sprintf(tmp, "%s:%s", schema->attrNames[attrNum], val ? "TRUE" : "FALSE");
            do
            {
                do
                {
                    if (result->bufsize < result->size + strlen(tmp))
                    {
                        int newbufsize = result->bufsize;
                        while ((newbufsize *= 2) < result->size + strlen(tmp))
                            ;
                        result->buf = realloc(result->buf, newbufsize);
                    }
                } while (0);
                memcpy(result->buf + result->size, tmp, strlen(tmp));
                result->size += strlen(tmp);
            } while (0);
            free(tmp);
        } while (0);
    }
    break;
    default:
        return "NO SERIALIZER FOR DATATYPE";
    }
    do
    {
        char *resultStr;
        do
        {
            resultStr = malloc((result->size) + 1);
            memcpy(resultStr, result->buf, result->size);
            resultStr[result->size] = '\0';
        } while (0);
        do
        {
            free(result->buf);
            free(result);
        } while (0);
        return resultStr;
    } while (0);
}

