functions.stringToValue:
Value *stringToValue(char *val)
{
    Value *result = (Value *)malloc(sizeof(Value));
    switch (val[0])
    {
    case 'i':
        result->dt = DT_INT;
        result->v.intV = atoi(val + 1);
        break;
    case 'f':
        result->dt = DT_FLOAT;
        result->v.floatV = atof(val + 1);
        break;
    case 's':
        result->dt = DT_STRING;
        result->v.stringV = malloc(strlen(val));
        strcpy(result->v.stringV, val + 1);
        break;
    case 'b':
        result->dt = DT_BOOL;
        result->v.boolV = (val[1] == 't') ? 1 : 0;
        break;
    default:
        result->dt = DT_INT;
        result->v.intV = -1;
        break;
    }
    return result;
}

functions.attrOffset:
RC attrOffset(Schema *schema, int attrNum, int *result)
{
    int offset = 0;
    int attrPos = 0;
    for (attrPos = 0; attrPos < attrNum; attrPos++)
        switch (schema->dataTypes[attrPos])
        {
        case DT_STRING:
            offset += schema->typeLength[attrPos];
            break;
        case DT_INT:
            offset += sizeof(int);
            break;
        case DT_FLOAT:
            offset += sizeof(float);
            break;
        case DT_BOOL:
            offset += sizeof(bool);
            break;
        }
    *result = offset;
    return 0;
}

