functions.valueEquals:
RC valueEquals(Value *left, Value *right, Value *result)
{
    if (left->dt != right->dt)
        do
        {
            RC_message = "equality comparison only supported for values of the same datatype";
            return 200;
        } while (0);
    result->dt = DT_BOOL;
    switch (left->dt)
    {
    case DT_INT:
        result->v.boolV = (left->v.intV == right->v.intV);
        break;
    case DT_FLOAT:
        result->v.boolV = (left->v.floatV == right->v.floatV);
        break;
    case DT_BOOL:
        result->v.boolV = (left->v.boolV == right->v.boolV);
        break;
    case DT_STRING:
        result->v.boolV = (strcmp(left->v.stringV, right->v.stringV) == 0);
        break;
    }
    return 0;
}

