functions.freeExpr:
RC freeExpr(Expr *expr)
{
    switch (expr->type)
    {
    case EXPR_OP: {
        Operator *op = expr->expr.op;
        switch (op->type)
        {
        case OP_BOOL_NOT:
            freeExpr(op->args[0]);
            break;
        default:
            freeExpr(op->args[0]);
            freeExpr(op->args[1]);
            break;
        }
        free(op->args);
    }
    break;
    case EXPR_CONST:
        freeVal(expr->expr.cons);
        break;
    case EXPR_ATTRREF:
        break;
    }
    free(expr);
    return 0;
}

